1	package scan
2	
3	import (
4		"fmt"
5		"regexp"
6		"strconv"
7		"strings"
8	)
9	
10	// Class values Trivy reports for a vulnerability result (Result.Class).
11	const (
12		// ClassOSPackages marks a package installed by the base image's package
13		// manager. A base image bump can clear it.
14		ClassOSPackages = "os-pkgs"
15		// ClassLangPackages marks an application dependency. Only a bump of the
16		// dependency itself clears it; a new base image changes nothing.
17		ClassLangPackages = "lang-pkgs"
18	)
19	
20	// FixCommand returns the command that moves pkg to version in the given
21	// ecosystem (Trivy's Result.Type), and false when no command is known — an
22	// ecosystem outside the table, or nothing to move to. It never invents one:
23	// "no command" is a real answer, and the caller shows the target version alone.
24	func FixCommand(ecosystem, pkg, version string) (string, bool) {
25		if pkg == "" || version == "" {
26			return "", false
27		}
28		switch ecosystem {
29		case "gomod", "gobinary":
30			return "go get " + pkg + "@v" + strings.TrimPrefix(version, "v"), true
31		case "npm", "node-pkg":
32			return "npm install " + pkg + "@" + version, true
33		case "yarn":
34			return "yarn add " + pkg + "@" + version, true
35		case "pnpm":
36			return "pnpm add " + pkg + "@" + version, true
37		case "pip", "pipenv", "python-pkg":
38			return "pip install " + pkg + "==" + version, true
39		case "poetry":
40			return "poetry add " + pkg + "==" + version, true
41		case "cargo", "rust-binary":
42			return "cargo update -p " + pkg + " --precise " + version, true
43		case "alpine":
44			return "apk upgrade " + pkg, true
45		case "debian", "ubuntu":
46			return "apt-get install --only-upgrade " + pkg, true
47		}
48		return "", false
49	}
50	
51	// versionNumbers matches the leading dotted number of a version, ignoring a
52	// "v" prefix. What follows (a pre-release, a distro revision such as -r0 or
53	// +deb11u3) is not part of the comparison, except as noted in CompareVersions.
54	var versionNumbers = regexp.MustCompile(`^v?(\d+(?:\.\d+)*)`)
55	
56	// parseVersion returns the dotted numbers of v and the text after them.
57	func parseVersion(v string) (nums []int, rest string, ok bool) {
58		v = strings.TrimSpace(v)
59		m := versionNumbers.FindStringSubmatch(v)
60		if m == nil {
61			return nil, "", false
62		}
63		for _, part := range strings.Split(m[1], ".") {
64			n, err := strconv.Atoi(part)
65			if err != nil {
66				return nil, "", false
67			}
68			nums = append(nums, n)
69		}
70		rest = v[len(m[0]):]
71		if strings.HasPrefix(rest, ":") {
72			// A Debian epoch ("1:1.1.1n"): the number before the colon outranks
73			// everything after it, so reading it as a version would misorder.
74			return nil, "", false
75		}
76		return nums, rest, true
77	}
78	
79	// CompareVersions orders two versions numerically, returning -1, 0 or 1 and
80	// true, or false when either has no leading number — a distro epoch such as
81	// "1:1.1.1n", a commit hash, a name. A missing component reads as zero
82	// (1.2 == 1.2.0), and a version with a "-" suffix sorts below the bare one
83	// (1.2.3-rc1 < 1.2.3). The result is a lenient ordering, not semver.
84	func CompareVersions(a, b string) (int, bool) {
85		an, ar, aok := parseVersion(a)
86		bn, br, bok := parseVersion(b)
87		if !aok || !bok {
88			return 0, false
89		}
90		for i := 0; i < max(len(an), len(bn)); i++ {
91			var x, y int
92			if i < len(an) {
93				x = an[i]
94			}
95			if i < len(bn) {
96				y = bn[i]
97			}
98			if x != y {
99				if x < y {
100					return -1, true
101				}
102				return 1, true
103			}
104		}
105		aPre, bPre := strings.HasPrefix(ar, "-"), strings.HasPrefix(br, "-")
106		switch {
107		case aPre && !bPre:
108			return -1, true
109		case !aPre && bPre:
110			return 1, true
111		}
112		return 0, true
113	}
114	
115	// PickFixed chooses the version to move to from Trivy's FixedVersion, which
116	// lists one fixed version per maintained branch ("1.2.4, 1.3.1"). It takes the
117	// lowest one on the installed version's major line, which is the smallest
118	// change that clears the CVE, and falls back to the lowest overall when no
119	// branch shares the major. A single value is returned as is, comparable or
120	// not; several that cannot be compared give "", because picking one of them
121	// would be a guess.
122	func PickFixed(installed, fixedIn string) string {
123		var options []string
124		for _, v := range strings.Split(fixedIn, ",") {
125			if v = strings.TrimSpace(v); v != "" {
126				options = append(options, v)
127			}
128		}
129		switch len(options) {
130		case 0:
131			return ""
132		case 1:
133			return options[0]
134		}
135	
136		instNums, _, instOK := parseVersion(installed)
137		best, bestSameMajor := "", false
138		for _, opt := range options {
139			nums, _, ok := parseVersion(opt)
140			if !ok {
141				return ""
142			}
143			same := instOK && len(instNums) > 0 && nums[0] == instNums[0]
144			switch {
145			case best == "":
146			case same && !bestSameMajor:
147			case same == bestSameMajor:
148				if c, _ := CompareVersions(opt, best); c >= 0 {
149					continue
150				}
151			default:
152				continue
153			}
154			best, bestSameMajor = opt, same
155		}
156		return best
157	}
158	
159	// fixInstruction is the sentence a finding carries when its ecosystem has no
160	// known command. The text is stored in the scan cache, so it must not change.
161	func fixInstruction(pkg, target string) string {
162		return fmt.Sprintf("Update %s to %s", pkg, target)
163	}
164	
165	// IsFixInstruction reports whether f.FixCommand is the sentence fixInstruction
166	// writes for f's package rather than a command the user can run. A caller shows
167	// a command as "Run: ..." and a sentence as plain text.
168	func IsFixInstruction(f Finding) bool {
169		if f.PkgName == "" {
170			return false
171		}
172		prefix := fixInstruction(f.PkgName, "")
173		return strings.HasPrefix(f.FixCommand, prefix) && len(f.FixCommand) > len(prefix)
174	}
