79	// oneLine is the first line of text, cut to width cells with theme.Ellipsis.
80	// It measures with x/ansi, as the viewport does, not with runewidth, after the
81	// tabs and carriage returns are gone: x/ansi counts a tab as no cell while the
82	// renderer lays it out as four spaces.
83	func oneLine(text string, width int) string {
84		if width <= 0 {
85			return ""
86		}
87		first, _, _ := strings.Cut(text, "\n")
88		first = withoutControlSpace(first)
89		if ansi.StringWidth(first) <= width {
90			return first
91		}
92		return ansi.Truncate(first, width, theme.Ellipsis)
93	}
94	
95	// cappedLines wraps text at min(width, maxMessageWidth), hard-breaking a token
96	// longer than that, and keeps the first maxLines lines. hidden counts the wrapped
97	// lines left out. A blank text gives nil, 0.
98	func cappedLines(text string, width, maxLines int) (lines []string, hidden int) {
99		if strings.TrimSpace(text) == "" {
100			return nil, 0
101		}
102		text = strings.TrimRight(text, " \t\r\n")
103		lines = strings.Split(ansi.Wrap(text, max(min(width, maxMessageWidth), 1), ""), "\n")
104		if len(lines) > maxLines {
105			return lines[:maxLines], len(lines) - maxLines
106		}
107		return lines, 0
108	}
109	
110	// moreLines is the marker after a capped text, "" when nothing was left out.
111	func moreLines(n int) string {
112		switch {
113		case n <= 0:
114			return ""
115		case n == 1:
116			return "… 1 more line"
117		}
118		return fmt.Sprintf("… %d more lines", n)
119	}
120	
121	// scrollPosition is "Lines a-b of N" when the content is taller than the
122	// viewport, "" otherwise.
123	func scrollPosition(offset, visible, total int) string {
124		if visible <= 0 || total <= visible {
125			return ""
126		}
127		offset = max(offset, 0)
128		return fmt.Sprintf("Lines %d-%d of %d", offset+1, min(offset+visible, total), total)
129	}
130	
131	// withoutControlSpace drops carriage returns and turns a tab into four spaces,
132	// which is how the renderer lays it out.
133	func withoutControlSpace(text string) string {
134		return strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\t", "    ")
135	}
136	
137	// normalizeText makes a scanner's text safe to lay out: a tab or a carriage
138	// return has no width the viewport and the terminal agree on, trailing spaces
139	// are noise, and a run of blank lines is one blank line. dropBlank removes the
140	// blank lines altogether (a stderr, where they separate nothing).
141	func normalizeText(text string, dropBlank bool) string {
142		text = withoutControlSpace(text)
143		var out []string
144		for _, line := range strings.Split(text, "\n") {
145			line = strings.TrimRight(line, " ")
146			blank := line == ""
147			switch {
148			case blank && (dropBlank || len(out) == 0 || out[len(out)-1] == ""):
149			default:
150				out = append(out, line)
151			}
152		}
153		for len(out) > 0 && out[len(out)-1] == "" {
154			out = out[:len(out)-1]
155		}
156		return strings.Join(out, "\n")
157	}
158	
159	// dropBlankLines is normalizeText without any blank line.
160	func dropBlankLines(text string) string { return normalizeText(text, true) }
161	
162	// detailsText lays text out for the finding detail: every line it returns is
163	// styled on the theme background and spans at most width cells, measured with
164	// x/ansi as the viewport does.
165	type detailsText struct {
166		width int            // cells a line may span
167		text  lipgloss.Style // ordinary text
168		dim   lipgloss.Style // secondary text
169	}
170	
171	func newDetailsText(width int) detailsText {
172		return detailsText{
173			width: width,
174			text:  lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText),
175			dim:   theme.DimStyle,
176		}
177	}
178	
179	// block wraps text at the full width, one styled line per entry.
180	func (t detailsText) block(text string, style lipgloss.Style) []string {
181		return t.indented("", text, style)
182	}
183	
184	// indented wraps text under a prefix of spaces.
185	func (t detailsText) indented(prefix, text string, style lipgloss.Style) []string {
186		text = normalizeText(text, false)
187		if text == "" {
188			return nil
189		}
190		var lines []string
191		for _, line := range t.wrapped(text, t.width-ansi.StringWidth(prefix)) {
192			if line == "" {
193				lines = append(lines, "")
194				continue
195			}
196			lines = append(lines, margin(ansi.StringWidth(prefix))+style.Render(line))
197		}
198		return lines
199	}

