	}{
		{"a plain command", "go get golang.org/x/net@v0.7.0", "go get golang.org/x/net@v0.7.0"},
		{"a command with spaces and a newline around it", "  go get golang.org/x/net@v0.7.0 \n", "go get golang.org/x/net@v0.7.0"},
